    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address actor, uint256 warpTime) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);

        uint256 sendAmt = 10;

        uint256 boundedWarp = bound(warpTime, 1, type(uint32).max);
        vm.warp(boundedWarp);

        vm.prank(actor);
        bool ok;
        try c.play{value: sendAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.pot() != 0);
        } else {
            return;
        }
    }
}
